(() => {
 'use strict';
 const A=window.LessonArticle, p=s=>'<p>'+s+'</p>', f=s=>'<p class="element-formula">'+s+'</p>';
 const sections=[
 ['target','最初に「何を・どこで」読むか決める',
 p('図の太枠を一つだけ見てください。四隅の点が「節点」、その4点で囲んだ一区画が「要素」、板全体に並べた網目が「メッシュ」です。実物の板は一枚のままです。計算では隣り合う四角形が辺の両端の節点を共有し、板を引っ張ればその節点は両方の要素で一緒に動きます。')+
 p('板全体の伸びを知るなら左右の端の変位差を、穴からの疲労き裂を検討するなら穴縁の応力を読みます。分割前に「左端からの距離」「穴縁からの角度」「板の表裏」「読む成分」を記録します。円孔縁では境界に沿う周方向応力が一例です。モデルを刻み直したときも同じ物理位置・方向・出力法で比べられます。')],
 ['ring','円孔を囲む四角形の帯',
 p('円周に沿って節点を並べ、対応する節点を外側へ結び、四角形の帯を作ります。円周方向の分割は曲線の近似と円周上の応力変化を、径方向の第1層の幅は穴から離れる方向の応力勾配を捉えます。一方だけ細かくすると要素が細長くなります。')+
 '<figure data-mesh-wave-lab="hole"></figure>'+
 p('今度は円周の分割数を固定し、「径方向の間隔」を切り替えてください。穴の輪郭は同じまま、穴に接する帯だけが外の帯より細くなるのが見えます。外側の角まで同じ節点列を追えるので、この操作で要素列が消えることはありません。図は全周を描いています。対称境界で一部だけ解析する場合は、荷重・支持・材料方向にも同じ対称性が必要です。')],
 ['features','段付き板と近接孔を、どこで細かく分けるか',
 '<h3>段付き板 ― 太い部分から細い部分へ移る丸みを見る</h3>'+
 p('厚さが一定で、途中で幅が40 mmから20 mmになる板を左右に引きます。細い側も同じ引張力を受け持つので、段から離れた部分の平均応力は太い側の2倍です。では、幅が切り替わる角ではどうでしょう。図の破線枠の中にある、小さな丸みを見てください。これが「肩の丸み」で、その半径をRと呼びます。')+
 window.MeshFeatureFigures.shoulder()+
 p('<strong>丸みの上と、丸みから板の中へ入った位置を比べます。</strong> 幅が切り替わる付近では応力が一様にならず、肩の縁に集中します。断面全体の平均からは、縁でどこまで応力が高くなるかは分かりません。まず円弧に沿って節点を置き、次にそこから板の内側にも数列を置きます。実物にあるRを直角に置き換えると、鋭い角の応力は分割を細かくするほど増え続ける場合があります。')+
 '<h3>近接孔 ― 二つの穴の間に残った板を見る</h3>'+
 p('直径12 mmの穴を上下に二つ、中心間隔16 mmで開けます。穴の縁から縁までには 16 − 6 − 6 = 4 mm の金属が残ります。「孔間の肉幅」とは、この金属の幅です。左右に引くと、穴の上下を回る材料に加えて、この4 mmの帯も力を受け持ちます。')+
 window.MeshFeatureFigures.holes()+
 p('<strong>二つの黒丸の間で、引張方向の応力がどう変わるかを見ます。</strong> 左図は穴の輪郭に沿って辺を並べてありますが、帯を横切ると要素は一つです。右図は同じ4 mmを4段に分けたので、穴の縁近くと帯の中央を別々の要素で調べられます。穴が板の端に近い場合も、穴の縁から板の端までに残る金属を同じように見ます。')+
 p('<strong>十分細かいかを確かめる方法。</strong> 図の6辺や4段は比較用です。肩なら丸みに沿った同じ位置、二つの穴なら同じ幅を横切る線で、同じ応力成分をもう一段細かい分割と比べます。応力の変化が緩やかになった外側で、四角形を徐々に大きくします。')],
 ['transition','全四角形で、列の幅を変える場合と本数を変える場合',
 p('同じ本数の列で辺の間隔だけ変えるなら、両側で対応する節点を順に結べます。列数も減らしたい場合は、平坦な部分に遷移用の面を区切ります。細かい側、粗い側、残る2辺の分割数をセットで設計するためです。')+
 p('公開されているFemapの実例では、3×3の領域と1×1の領域の間に専用の面を置き、四角形だけで移行させています。原資料の後半に完成形があります。作図後は内角・ゆがみを確認し、遷移を移したときに評価位置の応力が変わらないかを調べます。<a href="https://iberisa.wordpress.com/2015/05/17/2-d-transition-mesh-in-femap/" target="_blank" rel="noopener">作成者のFemap実例（全四角形の3対1遷移）</a>')+
 p('細かい側の節点を粗い要素の辺の途中に置いただけでは、通常のCQUAD4はその節点を参照しません。適合メッシュなら境界の各辺を両側の要素が同じ端点番号で参照することを確かめます。別メッシュを結ぶ意図なら、補間・接着などの結合条件を別に定義し、相対変位と力の受け渡しを検査します。<a href="theory.html#boundary/coincident">同じ座標の節点の使い分け</a>。')],
 ['shape','アスペクト比・スキュー・反りが測っているもの',
 p('正方形に描いた四角形の上辺を、その長さを変えずに横へずらしてみます。細長く引き伸ばした形とは違い、角が鋭くなります。次は一つの角だけを面の外へ持ち上げます。上から同じに見えても、今度は面が反ります。')+
 A.table(['見るもの','崩れたときの形','直し方'],[['アスペクト比','一方向だけ極端に長い。応力がその長い方向に急変すると捉えにくい','高い勾配を横切る向きに節点を追加する。辺比の定義は要素と検査ツールを確認'],['スキューとテーパー','長さがそろっていても菱形になったり、一端に幅が偏ったりする','分割点を動かし、幾何境界を描く列と内部の列を調整'],['四角形の反り','四隅が同じ平面上にない','曲率の強い方向を細分化し、節点順・法線を点検']])+
 p('検査結果は、ワースト値と要素番号を形状に戻して使います。評価点の近くなのか、荷重の伝わり方を左右する細い部分なのかで優先度が変わります。細長さだけで良否を一律には決められません。')],
 ['jacobian','ヤコビアンが正でも、精度は別に確かめる',
 '<figure data-mesh-wave-lab="shape"></figure>'+
 p('四角形の内側に小さな方眼を描いたと想像します。角を深く押し込むと、近くの升目は細くなり、さらに押すと裏返ります。この変化を数字で見つけるため、自然座標の小さな正方形を実際の四角形へ写し、局所的な面積の倍率と向きを調べます。これがヤコビ行列の行列式 det J です。平面要素の向きをそろえた規約では、0で局所面積がつぶれ、要素内で符号が変わると写像が折り返します。')+
 f('長方形の辺 a, b、自然座標 −1 ≤ ξ,η ≤ 1 の例<br>x = a(1+ξ)/2、y = b(1+η)/2<br>det J = (a/2)(b/2) = ab/4')+
 p('20×10 mmの長方形では50 mm²、相似な10×5 mmでは12.5 mm²です。小さい値だけを見て後者の形が悪いとは言えません。ヤコビアンそのものと、その要素内の最大・最小から得る品質指標を区別します。積分点・角のどこを検査したか、比の分子・分母、要素の種類をそろえて比較します。検出後の追い方は<a href="analysis.html#model-verification">解析のモデル検証</a>へ。')],
 ['study','粗・中・細で、同じ位置の同じ量を比較する',
 p('穴の上端の応力が143、155、158 MPaと変わったとします。増え方は小さくなっています。この差を分割の効果として読めるよう、荷重・境界・寸法・要素次数を保ち、評価領域の要素寸法hだけを段階的に小さくします。穴縁に近い要素中心は、細分化するたび縁へ近づきます。要素中心の値、外挿した縁の値、節点平均値を混ぜると、分割と評価位置の二つが同時に変わります。')+
 f('上の例示値の変化率（細かい側を分母とする）<br>粗→中：(155 − 143)/155 = 7.7 %<br>中→細：(158 − 155)/158 = 1.9 %')+
 p('1.9 %は最後の2メッシュの差です。真値に対する誤差ではありません。設計余裕と目的に照らし、必要ならもう一段刻み、応力勾配や分布も比較します。最大が増え続けるときは、点荷重・支持端・鋭い入隅を確認し、実際の荷重面積やRに基づく評価を選びます。')],
 ['modes','変位が収束しても、高次の振動数は別に調べる',
 p('片持ち板の先端を押したときのように全体が一方向にたわむ形と、途中で曲がる向きが何度も入れ替わる形を思い浮かべてください。後者は同じ長さの中により多くの節点が要ります。同じ片持ち板で1次の全体曲げを表せても、高次では節線の間に節点が足りない場合があります。分割を変えると近い固有値の順番が入れ替わるので、次数だけで対応づけず、変形方向・節線・対称性を見て同じモード形を追います。')+
 p('低次と対象上限付近の振動数、着目方向の有効質量、必要な位置の形状を並べます。質量の表し方・境界条件まで同時に変えると、メッシュの寄与を切り分けられません。<a href="analysis.html#modes">実固有値の結果を読む</a>。')],
 ['wavelength','波速と上限振動数から、最短波長を求める',
 p('地盤を1秒に200 m進む波が、1秒間に20回繰り返すとします。隣り合う山の間隔は200 ÷ 20 = 10 mです。もっと遅い層では同じ20回の山が短い距離に詰まります。等方弾性体のせん断波では、材料のせん断剛性Gと密度ρから波速が決まります。再現したい最高振動数を選べば、その材料で最も短い対象波長が分かります。波の進行方向に沿って要素寸法を比較します。')+
 f('Vs = √(G/ρ)　　周期 T = 1/f<br>1周期で波が進む距離 λs = Vs T = Vs/f<br>1波長をn要素で表す試算：h ≤ Vs/(n fmax)')+
 p('上の10 mの一波長を仮に10要素で描くなら、1要素は進行方向に1 mです。同じ周波数でもVs=100 m/sの軟らかい層では0.5 mになります。10分割は試算条件です。要素次数・許容位相誤差・波の伝播距離に応じて細分化し、波が届く時刻と振幅で確かめます。板や梁の曲げ波は波速が周波数で変わるため、このせん断波速度をそのまま使えません。')],
 ['time','空間刻み・積分時間刻み・出力間隔を分ける',
 p('周期0.05 sの成分を1周期20ステップで追う試算なら、積分刻みは0.0025 sです。まず同じメッシュで刻みだけ半分にし、ピークと位相を比較します。出力を10ステップおきにすると保存間隔は0.025 s、1周期あたり2点だけです。内部計算が細かくても、保存波形でピークを読み落とせます。')+
 p('陽解法にはさらに数値安定性の上限があります。単純な場合は要素の特性長さを伝播速度で割った時間が尺度になり、つぶれた小要素や速い波を通す材料が全体の刻みを制限します。短いS波を空間で捉える条件と、陽解法で速い波が小要素を通過する安定条件は別々に調べます。陰解法のSOL 109／112でも時間精度の検査は必要です。')+
 p('到達後に遅れて現れる別の山は、境界から戻った波かもしれません。<a href="theory.html#boundary/viscous">波の反射と粘性境界</a>で往復時間と照合します。')]
 ];
 const questions=[
 ['穴縁の径方向だけを細かくすると、円弧も滑らかになる？','穴の輪郭を作る円周方向の節点数は同じです。円弧の近似と、縁から内部への応力勾配は別に確認します。'],
 ['粗い辺の途中に細かい側の節点が重なる。力は伝わる？','座標の一致だけでは、その自由度を粗い側が参照しません。適合する要素接続か、意図した補間・接着条件が必要です。'],
 ['正方形を縦横半分にしたらdet Jは1/4。形が悪化した？','相似縮小で面積倍率が1/4になっただけです。写像がつぶれたり折り返したりしていないかを別に検査します。'],
 ['低次の固有振動数の変化が1 %なら、すべての高次にも適用できる？','対象上限付近のモード形と振動数を個別に追います。評価位置の応答にはその方向の励起とモードの寄与も関係します。'],
 ['Vs=180 m/s、30 Hzを1波長8分割で試すときの要素寸法は？','波長は180/30=6 m、進行方向の寸法は6/8=0.75 m以下が試算の出発点です。分割・時間刻みを別々に変えて到達時刻と波形を照合します。']
 ];
 sections.push(['questions','自分で確かめる',questions.map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')]);
 const guide=(name,page)=>'https://documentation-be.hexagon.com/bundle/MSC_Nastran_2025.1_'+name+'/raw/resource/enus/MSC_Nastran_2025.1_'+name+'.pdf#page='+page;
 const refs=[
 ['https://www.jstage.jst.go.jp/article/jsme1958/23/181/23_181_1043/_article/-char/ja/','二つの円孔をもつ帯板の引張り。孔の並び方と応力集中を調べた研究（日本機械学会）。'],
 [guide('Linear_Static_Analysis_User_Guide',342),'MSC 2025.1 線形静解析ガイド、第9章。等間隔・不等間隔の比較、粗密の移行位置。'],
 ['https://documentation-be.hexagon.com/bundle/Patran_2024.2_User_Guide/raw/resource/enus/Patran_2024.2_User_Guide.pdf','Patran 2024.2 第5章、本文pp.115–117。辺の分割と隣接領域。'],
 ['https://documentation-be.hexagon.com/bundle/Patran_2024.1_Reference_Manual_Part_3_Finite_Element_Modeling/raw/resource/enus/Patran_2024.1_Reference_Manual_Part_3_Finite_Element_Modeling.pdf','Patran 2024.1 Reference Manual Part 3 第11章。要素形状とヤコビアンの検査。'],
 [guide('Dynamic_Analysis_User_Guide',33),'MSC 2025.1 動解析ガイド、PDF 33・263頁。対象波長と積分時間刻み。'],
 [guide('Explicit_Nonlinear_SOL_700_User_Guide',107),'MSC 2025.1 SOL 700ガイド、第4章。要素別の安定時間刻み。'],
 ['https://www.nilim.go.jp/lab/bcg/siryou/tnn/tnn0429pdf/ks0429.pdf','国総研資料429号 §3.1。地震応答で対象周期とせん断波速度から刻みを決める例。'],
 ['https://iberisa.wordpress.com/2015/05/17/2-d-transition-mesh-in-femap/','IberisaによるFemapでの板のメッシュ遷移実例。']
 ];
 sections.push(['sources','参照資料',refs.map(([url,label])=>p('<a href="'+url+'" target="_blank" rel="noopener">'+label+'</a>')).join('')]);
 window.MeshChapter={sections,connect:root=>window.MeshWaveLabs.connect(root)};
})();
